      "synopsis": "En un evento aterrador e inesperado, todos los niños del mundo caen en un profundo estado catatónico. Tras un periodo de incubación de diez años, recuperan la conciencia y regresan con una furia incomprensible y violenta hacia los adultos. Sitges celebra el veinte aniversario de una película maldita con un director’s cut que muestra la visión creativa original de sus creadores. Esta sesión también sirve de homenaje a James Van Der Beek, fallecido en febrero de 2026.",
