      "synopsis": "Seijun Suzuki es una leyenda del cine. Su fuerza creativa e irreverente ligada a su audacia artística de los sesenta ha seguido influyendo en el cine contemporáneo, convirtiéndolo en padre espiritual de cineastas que han rendido tributo a su obra, como Quentin Tarantino o John Woo. El documental explora la visión de un verdadero creador de formas, además del universo desenfadado y violento de películas de culto como Tokyo Drifter y Branded to Kill.",
