      "synopsis": "La historia de amor entre José Mojica Marins y el Festival de Cine de Sitges se remonta a 1972, cuando, en su quinta edición, el festival catalán proyectó Esta noite encarnarei no teu cadáver. Fue en 1978 cuando el actor y director brasileño asistió por primera vez al festival. Más tarde volvería en 1997 y 2008, ya consolidado como una figura clave del cine de terror a nivel mundial. Este documental repasa las visitas de Marins al Festival con imágenes y documentos.",
