      "synopsis": "Tras salir de un centro psiquiátrico, un hombre desfigurado se obsesiona con una alumna del internado de su hermana, mientras trata de superar un turbio pasado. La genial aportación al boom del slasher de Jesús Franco fue esta clase maestra de diversión depravada que incluye estudiantes masacrados, incesto, voyeurismo y una discoteca sobre patines. El Festival recupera el filme en una nueva versión restaurada e íntegra.",
