      "synopsis": "Miles, un fotógrafo underground, captura retratos de desconocidos sin su permiso. Ahora bien, un día empieza a percibir algo inquietante: una misteriosa mujer lo fotografía a él, devolviéndole la mirada a través del objetivo. De repente, su mundo comienza a resquebrajarse: su trabajo es saboteado, su reputación queda destruida y sus seres queridos están en peligro. Consumido por la paranoia, se sumerge en una delirante obsesión por descubrir qué está ocurriendo.",
