      "synopsis": "Lionel Cosgrove tiene veinticinco años y nunca le han besado. Vive con su madre Vera, malvada como ella sola. Su vida se vuelve mucho más emocionante cuando conoce a Paquita y se enamora. Pero un simple mordisco en el brazo de su madre basta para que el mundo de Lionel se resquebraje. A medida que su madre, infectada, va perdiendo sus facultades mentales, Lionel lucha por mantener una apariencia de normalidad. Preview europeo de la restauración en 4K del clásico gore de Peter Jackson.",
