      "synopsis": "Ocho niños y dos monitores quedan atrapados en un refugio de los Pirineos cuando una tormenta de nieve corta todos los accesos. Sin electricidad, agua, ni forma de comunicarse, intentan resistir mientras llega el rescate. De pronto, se dan cuenta de que hay un niño de más, al que acogen temporalmente. A medida que el encierro se prolonga, el misterioso recién llegado se vuelve cada vez más agresivo y enigmático, sembrando la duda y el miedo en el grupo.",
