      "synopsis": "Para escapar de la monotonía de sus turnos de noche, Rok mata el tiempo robando chocolatinas en la gasolinera donde trabaja. Una noche conoce a una misteriosa joven con el rostro cubierto de hematomas. La chica, que solo aparece al anochecer, se dedica a combatir el crimen y asegura poseer superpoderes. Para volver a verla, Rok idea un insólito plan que dará un giro inesperado a su anodina existencia: robarle la bicicleta.",
