      "synopsis": "Basada en una famosa novela de la literatura fantástica para jóvenes escrita por Jean-Claude Mourlevat, The Upside Down River cuenta la historia del encuentro entre Tomek y Hannah durante su trayecto hacia el río Qjar. Hannah espera conseguir una gota mágica que pueda salvar a su pájaro; Tomek, por su parte, emprende un viaje para descubrir el vasto mundo. Sus aventuras se suceden, se entrelazan y, finalmente, acaban complementándose.",
