      "synopsis": "Chipre, 1882. Eleni, una pintora inmigrante en un pueblo bajo ocupación británica, pierde a sus hijos en un extraño accidente. Sumida en el dolor y la soledad, conoce a Michalakis, un joven con talento artístico sometido a abusos paternos. Con su ayuda, Eleni intenta resucitar a sus hijos, pero el ritual acaba invocando criaturas malignas que amenazan con llevarse al chico. Folk horror chipriota que narra una compleja historia de duelo y redención.",
