      "synopsis": "En circunstancias traumáticas, Gül da a luz a un ser que desafía las leyes de la naturaleza. Mientras su cuerpo y su mente se desmoronan, el amor por esa criatura inhumana se convierte en su mayor devoción y en su peor enfermedad. Aclamada por la crítica tras su paso por Tribeca, Mutter presenta una pesadilla febril sobre la maternidad, el duelo y la transformación: una fábula popular contemporánea donde la ternura y el terror conviven en un mismo plano.",
