      "synopsis": "En el East Forest Park de Hong Kong, la recolectora de basura Lan Pui Ching descubre un cadáver colgado que desentierra un oscuro secreto de su pasado. Mientras el agente de policía Huang Ming investiga una serie de accidentes sospechosos, Lan revela una verdad aterradora: estas muertes son asesinatos ocultos tras fuerzas sobrenaturales. Los hermanos Pang (The Eye, Re-cycle) regresan en plena forma con un trepidante filme de terror protagonizado por Josie Ho.",
