      "synopsis": "En 1975, una misteriosa mujer aparece en una reunión navideña y cuenta la historia de Tom, un ermitaño que, veinte años atrás, rescató a una actriz durante una tormenta de nieve. Para pasar la noche, la actriz comparte un relato aún más antiguo: una pareja de granjeros acoge a un joven vagabundo mientras una serie de asesinatos extiende el miedo por la frontera. Estas historias se entrelazan a través de varias generaciones para hablar de la venganza y el perdón.",
      "director": "Casey Affleck",
