      "synopsis": "América del Norte, en un futuro próximo. Dos parejas casadas y un hijo viven en un extraño piso que, en realidad, es un refugio antiatómico. El mundo ha quedado devastado por una guerra nuclear. El grupo espera con impaciencia a que desaparezca la radioactividad, mientras la convivencia entre ellos se va deteriorando. La obra maestra de la sci-fi postapocalíptica española de José Ulloa ha sido rescatada del olvido por Severin Films en una cuidada restauración.",
