      "synopsis": "Lee es un detective de policía estrella en Taipéi. Tras perder a su equipo durante la investigación de un delito, se ve torturado por la culpa y es trasladado a una comisaría rural. Traumatizado por el incidente, Lee sufre amnesia, pero está decidido a mantenerlo en secreto. Pronto le asignan un nuevo caso: el secuestro del hijo de un influyente empresario japonés. A medida que su memoria sigue desvaneciéndose, Lee solo puede confiar en su instinto.",
