      "synopsis": "Ambientada en la montaña de Langlang, la película narra la historia de cuatro pequeños monstruos —un jabalí, un sapo, una comadreja y un simio— a quienes el destino une. Inspirados en el querido clásico literario chino Viaje al Oeste, se disfrazan del monje Tang y sus discípulos y se embarcan en una aventura hilarante a la par que conmovedora. Animación china de altísimo nivel que explora temas universales como la familia, la amistad y los sueños.",
