      "synopsis": "A finales de los años 90, un grupo de niños pasa los días cantando y bailando en el mundo de It's Buddy!, un programa infantil presentado por un unicornio naranja brillante que vive en su extravagante club. Cuando uno de ellos se niega a seguir el juego, empiezan a aparecer grietas en ese mundo aparentemente perfecto. Absolutamente desquiciada, la propuesta de Kelly combina a la perfección el humor retorcido con el terror más extremo.",
