      "synopsis": "Hay que ser muy rico o muy estúpido para hacer una película. James y Francis no son ricos, así que optan por cometer una estupidez para financiar su primer largometraje: James vende su casa. Así comienza un viaje de varios años por el maravilloso, lucrativo y glamuroso mundo del cine independiente, donde nunca ocurre nada malo. Una historia sobre dos mejores amigos y lo que sucede cuando el sueño que comparten podría separarlos.",
