      "synopsis": "Slavik, un vagabundo ruso que asegura ser escritor, llega a una remota aldea donde Nina, una mujer fuerte e independiente mucho mayor que él, decide acogerlo. Lo que comienza como una insólita historia de amor acaba derivando en una traición que deja al descubierto las reglas ocultas del pueblo. Desde el Festival de Locarno llega esta íntima fábula que explora las raíces ocultas de la guerra entre Rusia y Ucrania.",
