      "synopsis": "Baldur, un joven de las islas Feroe del siglo XIX, intenta ganarse la vida como pescador. Su mundo se trastorna cuando conoce a Helge, un extraño ballenero por quien siente una fuerte atracción. Cuando una serie de violentas muertes sacude la zona, su romance se verá comprometido con su lucha por mantener a salvo al resto de los habitantes. Desde Fantasia llega esta propuesta de vampiros queer, con toques de folk horror y un marcado trasfondo gótico.",
