      "synopsis": "El domingo 23 de septiembre de 1984 se emitió Threads en la BBC2. Escrita por Barry Hines y dirigida por Mick Jackson, la película mostraba las consecuencias de un ataque termonuclear sobre la ciudad obrera de Sheffield. Las imágenes crudas del horror de la detonación, el colapso social y el invierno nuclear quedaron grabadas en decenas de millones de hogares. Sitges recupera esta obra maestra en una restauración en 4K a partir de los rollos originales de 16 mm.",
