      "synopsis": "Russell, un investigador universitario que estudia las abejas, acepta la ayuda de Patti, una misteriosa criadora de caniches, para financiar su investigación. Pero en el remoto rancho de la criadora descubrirá que toda oferta tiene un precio, y que las condiciones del trato son mucho más macabras de lo que jamás imaginó. Terror eugenésico altamente perturbador, que tuvo su estreno mundial en el Festival de Tribeca.",
