      "synopsis": "En un futuro no muy lejano, la gente vive casi exclusivamente de forma virtual debido a la mala calidad del aire. Carol, una desdichada madre y esposa, quiere volver a encarrilar su vida inscribiéndose en DreamQuil, un vanguardista retiro de bienestar digital. Sin embargo, cuando Carol regresa a casa, descubre que su familia ha estado conviviendo con Carol 2, un robot enviado por la empresa y diseñado para ayudarles en su ausencia.",
