      "poster": "https://sitgesfilmfestival.com/sites/default/files/styles/portrait_291x434/public/films/2026/aacd831c-b319-4097-aa3a-75f993fff0e0.jpg?itok=91mUXxuL",
      "synopsis": "En la comunidad china establecida en San Francisco, Ivy, una estudiante universitaria, trata de ayudar a su amiga Joy para que supere una traumática ruptura sentimental. Tras conocer por accidente al hermano de Joy, un chico con problemas mentales, Ivy se verá inmersa en una feroz espiral de violencia. Restauración en 4K de una de las joyas y rarezas más queridas por los amantes del cine hongkonés de los años ochenta.",
      "director": "Patrick Tam",
