      "synopsis": "Cuatro historias interrelacionadas giran en torno al panorama laboral actual: la cultura del estrés de una empresa de marketing, el interminable y repetitivo trabajo de un repartidor de comida, los horrores en línea a los que se enfrenta un moderador de contenidos y la sindicalización de una cafetería de barrio. Comedia negra indie con toques de terror que confirma la valía de nuevas voces del cine de género yanqui como Brea Grant y Chelsea Stardust.",
