      "synopsis": "Crossley, un misterioso viajero, irrumpe en la vida de una joven pareja, Rachel y Anthony Fielding. Anthony es compositor y experimenta con efectos de sonido y diversas fuentes electrónicas en su apartado estudio de Devon. La pareja acoge a Crossley, pero sus intenciones se van revelando poco a poco como algo siniestro. Afirma que ha aprendido de un chamán aborigen a emitir un grito del terror capaz de matar a cualquiera que lo oiga sin protección.",
