      "synopsis": "Tras el éxito de A quemarropa y Deliverance, Warner Brothers le ofreció a John Boorman la oportunidad de su vida: dirigir una secuela de El exorcista. El resultado fue una de las películas más controvertidas de la historia del cine. Cincuenta años después de su estreno, John Boorman, Linda Blair, Louise Fletcher, Karyn Kusama, Joe Dante y Mike Flanagan, entre otros, reflexionan sobre la ambición del filme, el arte y el oficio, y el valor de los grandes riesgos creativos.",
