      "synopsis": "Homenaje a uno de los narradores más visionarios de la televisión: Rod Serling. A partir de grabaciones inéditas, la película muestra al hombre detrás de The Twilight Zone en toda su complejidad, mientras transformaba la conciencia social y la imaginación en un arte atemporal. Un retrato íntimo de un artista que luchó contra el trauma, la censura y la fama, sin renunciar nunca a la convicción de que contar historias podía seguir teniendo un propósito moral.",
