      "synopsis": "Ren, un joven que evita enfrentarse a los problemas, visita con su novia un remoto complejo turístico junto a un lago. Aunque parecen estar unidos, entre ellos persiste una tensión no expresada. El lugar parece el refugio perfecto, pero con el paso de los días, Ren se siente cada vez más incómodo. La escapada se convertirá en pesadilla cuando, sin saberlo, ambos se vean envueltos en un extraño ritual relacionado con el poder purificador del agua.",
