      "synopsis": "Tras la muerte de su padre en el mar, Jay Gardiner se sumerge en la costa central de California en busca de su cuerpo, pero pronto es engullido por un enorme cachalote. Mientras permanece atrapado en su vientre, con solo una hora de oxígeno restante, Jay se da cuenta de que las lecciones que su padre le enseñó con tanto esfuerzo pueden ser la clave para salvar su vida. Survival marino que redefine el subgénero del terror en el agua de una manera festiva, única y muy emocionante.",
