      "synopsis": "Con el sueño de formar una familia, Saga y Jon se mudan a la casa donde ella creció, en el corazón de los bosques finlandeses. Sin embargo, tras el nacimiento de su bebé, el deseo de tener un hijo perfecto se transforma en una auténtica pesadilla. Mientras todos intentan tranquilizarla, Saga es la única persona capaz de percibir la aterradora verdad. Tras Ego, Bergholm vuelve al Festival con un inquietante folk horror sobre la depresión posparto.",
