      "synopsis": "Philip Doom, un acaudalado magnate empresarial estadounidense, intenta recuperar el contacto con su hija Madeleine durante un lujoso viaje a París. Pero la gastronomía francesa, una película de terror de los años cincuenta y una empleada del hotel demasiado entrometida, se convertirán en una amenaza inesperada que pondrá en riesgo el buen desarrollo y el propósito de su viaje. El director francés más excéntrico y genial regresa al Festival en plena forma.",
