      "synopsis": "Retrato íntimo de Stuart Cornfeld, uno de los productores más fascinantes del cine independiente estadounidense. A través de las apariciones estelares de cineastas como David Lynch, Steven Soderbergh o Guillermo del Toro, se exploran las inseguridades y la humanidad del “culpable” de clásicos contemporáneos como El hombre elefante, La mosca o Zoolander. Un biopic ingenioso que desvela magníficas anécdotas de algunos de los mejores rodajes de Hollywood.",
