      "synopsis": "Tras perder a su amigo Poupelle, el niño Lubicchi se adentra en el misterioso reino conocido como la Fortaleza del Milenio, donde una torre del reloj se ha detenido a las 23:59. Para regresar a casa, debe volver a ponerla en marcha. Junto a su gato Fluff, comienza a desentrañar su misterio y encontrará el valor para recuperar su fe. Esperadísima secuela de Poupelle of Chimney Town (2020), que, tras su exitoso paso por la Berlinale, aterriza en Sitges.",
