      "synopsis": "Guiados por la voz de la actriz Charlotte Rampling, nos adentramos en el laberíntico universo del cineasta Chris Marker, quien pasó toda una vida ocultándose tras seudónimos e imágenes de gatos. A través de una constelación de documentos personales y fragmentos de películas, un archivista intenta descifrar al autor a partir de las huellas materiales que dejó tras de sí. Debackere construye una meditación sobre la memoria, la identidad y el poder de las imágenes del pasado.",
