      "synopsis": "Chile, 1989. El régimen de Pinochet está en decadencia y Udo Berger, campeón de juegos de guerra de mesa, pasa las vacaciones con su novia en un balneario. Cuando otro turista se pierde misteriosamente, Udo decide no buscar a su amigo desaparecido, sino invitar a un misterioso lugareño a jugar una partida. Formidable adaptación de El Tercer Reich de Roberto Bolaño, en la que Scherson captura con maestría la furia y la jovialidad de la obra original.",
      "director": "Alicia Scherson",
