      "synopsis": "Cuando una pareja desaparece cerca del embalse de Salmokji y una figura no identificada aparece en las imágenes de Street View, un equipo de rodaje, liderado por Su-in, regresa al lugar para repetir la grabación. Allí empezarán a experimentar fenómenos perturbadores sin ninguna explicación. Atmosférico y trepidante found footage que se convirtió en la película de género más taquillera de la historia de República de Corea, superando a Dos hermanas.",
