      "synopsis": "Mirjana, una detective introvertida y adicta a su trabajo, llega a una aislada población de la zona rural de Serbia para investigar la desaparición de una chica. Una vez allí, descubrirá que los habitantes del lugar custodian un secreto relacionado con una criatura fantástica procedente de las leyendas populares del pueblo. El sentido de la maravilla y el folklore fantastique balcánico se citan en una película única dentro del cine de género europeo reciente.",
