      "synopsis": "La extraordinaria historia jamás contada sobre el rodaje de La chaqueta metálica, un viaje marcado por la obsesión, el conflicto y la innovación. A partir de testimonios de más de 40 miembros del equipo, el documental nos introduce en el exigente proceso creativo de Kubrick a través de una mirada íntima y excepcional. El retrato de un artista que se llevó a sí mismo —y a todos los que le rodeaban— más allá de los límites de lo posible.",
