      "synopsis": "Wisconsin, 1870. El pequeño pueblo de Friendship, habitado por colonos escandinavos, sigue sufriendo las secuelas de la reciente Guerra Civil. Cuando una nueva amenaza, todavía más letal, se cierne sobre la comunidad, el sheriff deberá enfrentarse a una decisión desgarradora: salvar a su joven familia o defender a la comunidad que le brindó una segunda oportunidad en la vida. Impactante debut basado en la novela homónima de Stewart O'Nan.",
