      "synopsis": "La mirada definitiva desde dentro de Star Trek, el icónico fenómeno de la cultura pop que, durante seis décadas, ha hecho mucho más que entretener: ha desafiado, provocado y redefinido los límites de la televisión. A través de entrevistas exclusivas con estrellas, guionistas, directores y productores, este épico documental revela cómo decisiones artísticas, conflictos e ideas revolucionarias confluyeron para crear un clásico televisivo inmortal.",
