      "venue": "Sala Tramuntana Meliá",
      "duration": "103 min",
      "image": "forest",
      "poster": "https://sitgesfilmfestival.com/sites/default/files/styles/portrait_291x434/public/films/2026/45ba8cc5-f516-4521-82ad-b61f8abd889f.jpg?itok=KDFwTJrR",
      "synopsis": "Mike Tyler es una estrella de cine que tras sufrir una crisis ansía volver a ser el centro de atención. Su primera reaparición pública en una gala benéfica contra el cambio climático se verá eclipsada por la irrupción en escena de un grupo antisistema radical liderado por la entusiasta Joan. El combativo e iconoclasta director de Atenea entrega una sátira salvaje sobre el mundo actual con un reparto de lujo encabezado por Chris Evans y Anya Taylor-Joy.",
      "director": "Romain Gavras",
