      "synopsis": "Con la intención de seguir la fiesta, cuatro jóvenes acaban en el refugio —repleto de drogas— del inestable hijo de un mafioso. Tras una decisión precipitada, la noche se convierte en un caos paranoico en el que Eden y sus amigas deberán luchar por sobrevivir. Con unas secuencias de violencia física que recuerdan a la brutalidad de Green Room, este trepidante thriller recién llegado del Festival de Toronto deleitará a los fans del gore más despiadado.",
