      "synopsis": "La doncella Chang Er emprende un viaje hacia la cara oculta de la Luna en busca de su amante, Hou Yi, un arquero que ha desaparecido durante su misión para salvar al sol moribundo. En el camino, se enamora de su acompañante, un astronauta procedente de la Tierra. Mitología china ancestral llegada directamente de Locarno, en la que la ciencia ficción y el wuxia se entremezclan para hablar de la alienación a través de una sucesión de imágenes impactantes.",
