      "synopsis": "Beniko y su hija desaparecen, dejando tras de sí una única pista: misteriosas huellas de oni (ogro del folclore japonés). Diez años después, su marido empieza a buscarlas tras descubrir que quizá sigan con vida. Sus pesquisas lo conducen a Shinonashi, donde Beniko ha estado viviendo junto a su familia. Obra de teatro filmada que trata los valores del amor y el sacrificio a través de un relato sobre el destino y el linaje de su protagonista.",
