      "synopsis": "En el desierto, numerosos grupos luchan por el poder. Dao Ma, un famoso cazarrecompensas, acepta un encargo para proteger a un hombre en el largo camino hacia la ciudad de Chang’an. Sin embargo, descubre que la persona a la que protege es el individuo más buscado del imperio: Zhi Shi Lang. Ahora, todas las facciones codiciosas les persiguen, y comienza una batalla mortal por la recompensa. Cuatro generaciones de estrellas chinas de las artes marciales se reúnen para ofrecer un espectáculo épico de acción.",
