      "synopsis": "En 2017, el recién nombrado secretario de Seguridad de Hong Kong desaparece sin dejar rastro. Desesperado por encontrar respuestas, el comisario de policía recurre a un abogado, quien consigue desbloquear un expediente clasificado de 1994. Tercera entrega de la saga Cold War, que funciona como precuela de las anteriores y anticipa una cuarta película, Cold War 1995. Su reparto reúne a diez ganadores del premio a Mejor Actor de los Hong Kong Film Awards.",
