      "synopsis": "19, un soldado de la Infantería Genética, cae accidentalmente tras las líneas enemigas en medio de una operación militar secreta. Con las identidades de sus compañeros fallecidos guardadas en biochips que lleva en su rifle, mochila y pistola, 19 debe informar a sus superiores de que la misión se ha ido al traste. El director de Moon y Código fuente se pasa a la animación para adultos adaptando un conocido cómic de la revista 2000 AD.",
