      "synopsis": "Sean y Kim son una pareja al borde del divorcio que alquila su casa de invitados a dos hermanos de carácter reservado. Lo que comienza como una solución práctica para ganar dinero, pronto se convierte en una espiral de paranoia cuando suceden una serie de extraños acontecimientos —luces misteriosas, animales que desaparecen— los días previos a la visita del presidente de los Estados Unidos a la ciudad. Provocador thriller que llega directamente del SXSW de Austin.",
