      "synopsis": "Tras la repentina muerte de su madre en la fábrica, Putri sospecha que en realidad se trató de un suicidio, mientras que su hermana, Ida, está convencida de que fue algo mucho más siniestro: una posesión. Decidida a demostrarlo, Ida acepta un trabajo en la misma fábrica y trabaja día y noche para descubrir qué fue lo que realmente se llevó el cuerpo de su madre. Desde Indonesia llega una de las muestras de terror asiático más estimulantes del año.",
