      "synopsis": "Serena, administradora de Paradiso Palms, descubre una muerte inquietante dentro del edificio. Lo que parece el inicio de un brote vírico revela pronto una amenaza mucho más aterradora: una nueva especie de arañas venenosas se propaga rápidamente por el complejo. Con el edificio en cuarentena y los residentes atrapados, Serena deberá usar su conocimiento del lugar para liderar la lucha por la supervivencia mientras se enfrenta a sus propios miedos.",
