      "synopsis": "Nueva antología de terror de la saga V/H/S/ donde su característico found footage explora el poder de la música, el ritmo y el audio para atormentar, poseer, transformar y destruir. La película combina el horror cósmico, el suspense psicológico, el splatter más descabellado y unos efectos especiales innovadores, en una inolvidable recopilación de pesadillas. En V/H/S/MIXTAPE la música y el sonido se convierten en la fuente del terror.",
