      "synopsis": "Un antropólogo se adentra en la selva amazónica en una misión de rescate, donde recupera las imágenes grabadas por un equipo de rodaje que documentaba sus desastrosos encuentros con tribus caníbales locales. La obra maestra de Ruggero Deodato que inventó el found footage moderno, cruzándose con el cine de caníbales más salvaje, vuelve a la vida en 4K con un nuevo montaje que incluye material inédito.",
