      "synopsis": "Con estética de falso documental, I Love Paris sigue a una cantante parisina que, tras convertirse en vampira, persigue la fama a costa de su alma. Explosiva y vibrante, no es solo una película de vampiros, sino también un filme sobre música en el que la vida nocturna brilla con fuerza. Desde Fantasia llega esta divertida propuesta de terror que, mezclando el humor australiano con la naturalidad francesa, construye un relato tan enérgico como hipnotizante.",
