      "synopsis": "Margot, una médica residente en prácticas en el servicio de urgencias más competitivo de Francia, tiene dificultades para cumplir con las exigencias de su puesto. Mientras atiende a varios pacientes de su edad que presentan síntomas inusuales, su propio cuerpo empieza a experimentar una inquietante transformación. La heredera centennial de Crudo convierte el malestar de las nuevas generaciones en una explosión de body horror deliciosa.",
