      "synopsis": "Airi, una médium que ayuda a las almas perdidas a cruzar al más allá, es solicitada en una aislada casa de campo, un lugar donde deberá enfrentarse a una poderosa entidad. Mientras investiga el oscuro pasado de la vivienda y el origen de la presencia sobrenatural, descubre un secreto oculto que la convierte en el blanco de una amenaza mortal. Por primera vez, su mayor adversario no proviene del mundo de los espíritus, sino del de los vivos.",
