      "synopsis": "Ziggy y sus cuatro amigos se van de acampada a un bosque aislado y pintoresco. Al adentrarse en una zona prohibida, despiertan un terror espeluznante en el bosque y un hambre voraz que surge de las entrañas de la Tierra. Y es que el propio suelo intenta devorar, literalmente, a todos aquellos que lo pisan. Los directores de Starry Eyes y el remake de Cementerio de animales vuelven al terror indie con excelentes resultados.",
