      "synopsis": "Meg, una científica forense, ve cómo su vida da un vuelco cuando el cuerpo de su padre, desaparecido hace treinta y seis años, aparece inexplicablemente en una macabra escena del crimen. A medida que surgen nuevas víctimas, Meg se adentra en una investigación que desentierra los secretos más oscuros de su padre y la enfrenta a una presencia sobrenatural que lleva décadas acechando al pueblo. Calificada por Stephen King como una de las mejores películas de terror de 2026.",
