      "synopsis": "En las afueras de un pueblo costero vive una pescadora soltera, objeto de burlas constantes. Harta del conservadurismo de sus vecinos, encarga al artesano local que le fabrique un marido de mimbre. Este peculiar romance, sumado a la perfección del nuevo amante, desatará la indignación, los celos y el caos en la comunidad. Audaz fábula en clave de comedia sobre el sexo, el matrimonio y lo absurdo de las convenciones sociales.",
