      "synopsis": "En Daca, Zaineen se prepara para su boda siguiendo los rituales de belleza y las expectativas familiares. Sin embargo, su cuerpo reacciona de muchas formas inesperadas. Entre remedios caseros, presiones sociales y visiones inquietantes, el camino hacia el matrimonio se convierte en una lucha física y psicológica contra lo que se le impone. Una de las películas más destacadas de la sección Orizzonti del pasado Festival de Venecia.",
